from pathlib import Path
import shutil
out = Path('/app/output')
keep = {'gen.py', 'trajectory.npz'}
for path in out.iterdir():
    if path.name in keep:
        continue
    if path.is_dir():
        shutil.rmtree(path)
    else:
        path.unlink()
print(sorted(p.name for p in out.iterdir()))
